int pqcp_runtime_authorization_policy_lookup(
	enum pqcp_runtime_authorization_condition condition,
	enum pqcp_runtime_command_kind command,
	struct pqcp_runtime_authorization_policy_decision *decision)
{
	if (condition < PQCP_RUNTIME_AUTHORIZATION_ANONYMOUS ||
	    condition >= PQCP_RUNTIME_AUTHORIZATION_CONDITION_COUNT ||
	    command < PQCP_RUNTIME_COMMAND_NONE ||
	    command >= PQCP_RUNTIME_COMMAND_KIND_COUNT ||
	    decision == NULL) {
		return -EINVAL;
	}
	*decision = runtime_authorization_catalog[condition][command];
	return 0;
}

int pqcp_runtime_authorization_policy_catalog_audit(void)
{
	for (size_t condition = 0U;
	     condition < PQCP_RUNTIME_AUTHORIZATION_CONDITION_COUNT; ++condition) {
		for (size_t operation = 0U;
		     operation < PQCP_RUNTIME_POLICY_COMMAND_COUNT; ++operation) {
			const struct pqcp_runtime_authorization_policy_decision *entry =
				&runtime_authorization_catalog[condition][operation];

			if ((size_t)entry->condition != condition ||
			    (size_t)entry->command != operation ||
			    entry->disposition >
				PQCP_RUNTIME_AUTHORIZATION_QUARANTINE ||
			    entry->reason_mask == 0U) {
				return -EBADMSG;
			}
			if (entry->disposition ==
				    PQCP_RUNTIME_AUTHORIZATION_DENY &&
			    entry->error == 0) {
				return -EBADMSG;
			}
		}
	}
	return 0;
}
